from collections import deque

def measure(bucket_one, bucket_two, goal, start_bucket):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Validate inputs
    if not isinstance(bucket_one, int) or not isinstance(bucket_two, int) or bucket_one <= 0 or bucket_two <= 0:
        raise ValueError("Bucket sizes must be positive integers.")
    if not isinstance(goal, int) or goal < 0:
        raise ValueError("Goal must be a non-negative integer.")
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'.")

    max_cap = max(bucket_one, bucket_two)
    if goal > max_cap:
        raise ValueError("Goal cannot be greater than both bucket sizes.")
    if goal == 0:
        # No actions needed to have 0 liters
        return (0, start_bucket, 0)
    if goal % gcd(bucket_one, bucket_two) != 0:
        raise ValueError("Goal cannot be measured with these bucket sizes.")

    # Initial state after first action: fill the starting bucket
    if start_bucket == "one":
        start_state = (bucket_one, 0)
    else:
        start_state = (0, bucket_two)

    # Check immediate goal
    if start_state[0] == goal:
        return (1, "one", start_state[1])
    if start_state[1] == goal:
        return (1, "two", start_state[0])

    # BFS to find minimal actions
    q = deque()
    q.append((start_state[0], start_state[1], 1))  # vol1, vol2, moves
    visited = set()
    visited.add((start_state[0], start_state[1]))

    while q:
        vol1, vol2, moves = q.popleft()

        # generate possible next states (each action counts as one move)
        candidates = []

        # Fill bucket one
        candidates.append((bucket_one, vol2))
        # Fill bucket two
        candidates.append((vol1, bucket_two))
        # Empty bucket one
        candidates.append((0, vol2))
        # Empty bucket two
        candidates.append((vol1, 0))
        # Pour one -> two
        pour = min(vol1, bucket_two - vol2)
        candidates.append((vol1 - pour, vol2 + pour))
        # Pour two -> one
        pour = min(vol2, bucket_one - vol1)
        candidates.append((vol1 + pour, vol2 - pour))

        for nvol1, nvol2 in candidates:
            # enforce forbidden state: after any action, you may not have the starting bucket empty and the other full.
            if start_bucket == "one" and nvol1 == 0 and nvol2 == bucket_two:
                continue
            if start_bucket == "two" and nvol2 == 0 and nvol1 == bucket_one:
                continue

            if (nvol1, nvol2) in visited:
                continue
            # check goal
            if nvol1 == goal:
                return (moves + 1, "one", nvol2)
            if nvol2 == goal:
                return (moves + 1, "two", nvol1)
            visited.add((nvol1, nvol2))
            q.append((nvol1, nvol2, moves + 1))

    # If BFS completes without finding a solution (shouldn't happen due to gcd check)
    raise ValueError("No solution found with the given parameters and start bucket.")
